ALTER TABLE "notifications_telegramdelivery" ALTER COLUMN "telegram_message_ids" DROP DEFAULT;
--
-- Create model BroadcastSource
--
CREATE TABLE "notifications_broadcastsource" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "chat_id" bigint NOT NULL, "media_group_id" varchar(128) NOT NULL, "messages" jsonb NOT NULL, "state" varchar(16) NOT NULL, "sealed_at" timestamp with time zone NULL, "quiet_until" timestamp with time zone NOT NULL, "deadline" timestamp with time zone NOT NULL, "error_category" varchar(64) NOT NULL, "created_at" timestamp with time zone NOT NULL, "operator_id" bigint NOT NULL);
--
-- Add field copy_source to broadcastcampaign
--
ALTER TABLE "notifications_broadcastcampaign" ADD COLUMN "copy_source_id" bigint NULL CONSTRAINT "notifications_broadc_copy_source_id_554fb5b6_fk_notificat" REFERENCES "notifications_broadcastsource"("id") DEFERRABLE INITIALLY DEFERRED; SET CONSTRAINTS "notifications_broadc_copy_source_id_554fb5b6_fk_notificat" IMMEDIATE;
--
-- Add field copy_source to telegramdelivery
--
ALTER TABLE "notifications_telegramdelivery" ADD COLUMN "copy_source_id" bigint NULL CONSTRAINT "notifications_telegr_copy_source_id_eda8da40_fk_notificat" REFERENCES "notifications_broadcastsource"("id") DEFERRABLE INITIALLY DEFERRED; SET CONSTRAINTS "notifications_telegr_copy_source_id_eda8da40_fk_notificat" IMMEDIATE;
--
-- Create model InAppAnnouncement
--
CREATE TABLE "notifications_inappannouncement" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "public_id" uuid NOT NULL UNIQUE, "audience" varchar(8) NOT NULL, "state" varchar(16) NOT NULL, "title_snapshot" varchar(200) NOT NULL, "body_snapshot" text NOT NULL, "channel" varchar(16) NOT NULL, "recipient_upper_bound" bigint NOT NULL CHECK ("recipient_upper_bound" >= 0), "estimated_recipients" bigint NOT NULL CHECK ("estimated_recipients" >= 0), "cursor" bigint NOT NULL CHECK ("cursor" >= 0), "processed_count" bigint NOT NULL CHECK ("processed_count" >= 0), "attempt_count" smallint NOT NULL CHECK ("attempt_count" >= 0), "next_attempt_at" timestamp with time zone NULL, "error_category" varchar(64) NOT NULL, "created_at" timestamp with time zone NOT NULL, "confirmed_at" timestamp with time zone NULL, "completed_at" timestamp with time zone NULL, "cancelled_at" timestamp with time zone NULL, "confirmed_by_id" integer NULL, "created_by_id" integer NOT NULL, "player_id" bigint NULL, "template_id" bigint NOT NULL);
--
-- Create constraint broadcast_operator_album on model broadcastsource
--
CREATE UNIQUE INDEX "broadcast_operator_album" ON "notifications_broadcastsource" ("operator_id", "media_group_id") WHERE NOT ("media_group_id" = '');
