--
-- Create constraint announcement_exact_audience on model inappannouncement
--
ALTER TABLE "notifications_inappannouncement" ADD CONSTRAINT "announcement_exact_audience" CHECK ((("audience" = 'ALL' AND "player_id" IS NULL) OR ("audience" = 'ONE' AND "player_id" IS NOT NULL)));
ALTER TABLE "notifications_broadcastsource" ADD CONSTRAINT "notifications_broadc_operator_id_62309a57_fk_notificat" FOREIGN KEY ("operator_id") REFERENCES "notifications_botadminoperator" ("id") DEFERRABLE INITIALLY DEFERRED;
