ALTER TABLE "notifications_inappannouncement" ADD CONSTRAINT "notifications_inappa_template_id_e7958ca1_fk_notificat" FOREIGN KEY ("template_id") REFERENCES "notifications_notificationtemplate" ("id") DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX "notifications_inappannouncement_state_eeb36043" ON "notifications_inappannouncement" ("state");
CREATE INDEX "notifications_inappannouncement_state_eeb36043_like" ON "notifications_inappannouncement" ("state" varchar_pattern_ops);
